(()=>{const e="/blog/pages/adult/";fetch("/blog/pages/adult/manifest.json",{cache:"no-store"}).then(e=>{if(!e.ok)throw new Error(`Adult blog manifest: ${e.status}`);return e.json()}).then(t=>{window.BLOG_DISCOVERY_CONFIG=Object.freeze({sourceDir:e,posts:Object.freeze((t.files||[]).map(t=>`${e}${t}`)),pinned:Object.freeze((t.pinned||[]).map(t=>`${e}${t}`)),mostSearched:Object.freeze((t.mostSearched||[]).map(t=>`${e}${t}`)),symptoms:Object.freeze(t.symptoms||[]),clusters:Object.freeze(t.clusters||[])}),window.dispatchEvent(new CustomEvent("blogConfigLoaded"))}).catch(()=>{window.BLOG_DISCOVERY_CONFIG={sourceDir:e,posts:["overthinking-vs-anxiety.html","scheduled-worry-time-technique.html","sleep-and-anxiety-cycle.html","stimulus-control-therapy.html","when-to-see-a-psychiatrist.html"].map(t=>`${e}${t}`),pinned:[],mostSearched:[],symptoms:[],clusters:[]},window.dispatchEvent(new CustomEvent("blogConfigLoaded"))})})();